```javascript
// 1. 先显示一个进度未满的进度条作为销毁对象
eda.sys_LoadingAndProgressBar.showProgressBar(50, '嘉立创示例 正在处理');
console.log('进度条已显示，当前进度 50%');
await new Promise(r => setTimeout(r, 800));

// 2. 销毁进度条（同步调用，无返回值）
eda.sys_LoadingAndProgressBar.destroyProgressBar();
console.log('进度条已销毁');
```
